INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7253829, 1127346, 150277, '<td valign="top">I love the silhouettes.  I felt happy when I saw this image, the boy looks a bit like he is skipping.</td>', 'I love the silhouettes.  I felt happy when I saw this image, the boy looks a bit like he is skipping.', '2014-08-22 15:10:56.000000', NULL, 1),
(7253830, 1127279, 150277, '<td valign="top">Beautiful and serene.  Wonderful colors.</td>', 'Beautiful and serene.  Wonderful colors.', '2014-08-22 15:11:20.000000', NULL, 1),
(7253831, 1127431, 150277, '<td valign="top">Neat.</td>', 'Neat.', '2014-08-22 15:11:29.000000', NULL, 1),
(7253866, 1127357, 124982, '<td valign="top">Nice leading line with the staircase, but too overprocessed for my liking.</td>', 'Nice leading line with the staircase, but too overprocessed for my liking.', '2014-08-22 20:12:09.000000', NULL, 1),
(7253867, 1127415, 124982, '<td valign="top">I love the stark nature of the yellow stem/leaf...would''ve looked so wonderful when contrasted against nice bluish water and not the unfortunate brown water (beyond your control, I accept).</td>', 'I love the stark nature of the yellow stem/leaf...would''ve looked so wonderful when contrasted against nice bluish water and not the unfortunate brown water (beyond your control, I accept).', '2014-08-22 20:13:34.000000', NULL, 1),
(7253868, 1127495, 124982, '<td valign="top">Wish her face wasn''t so underexposed. Otherwise, like the composition.</td>', 'Wish her face wasn''t so underexposed. Otherwise, like the composition.', '2014-08-22 20:15:06.000000', NULL, 1),
(7253871, 1127569, 124982, '<td valign="top">Crap?</td>', 'Crap?', '2014-08-22 20:18:32.000000', NULL, 1),
