(7253874, 1127027, 124982, '<td valign="top">Awesome textures and patterns. Quite lovely!</td>', 'Awesome textures and patterns. Quite lovely!', '2014-08-22 20:20:30.000000', NULL, 1),
(7253875, 1127567, 124982, '<td valign="top">Gorgeous lighting and texture!</td>', 'Gorgeous lighting and texture!', '2014-08-22 20:20:56.000000', NULL, 1),
(7253876, 1127582, 124982, '<td valign="top">Ourageously fantastic. Just my kind of image!!</td>', 'Ourageously fantastic. Just my kind of image!!', '2014-08-22 20:22:03.000000', NULL, 1),
(7253884, 1127402, 124982, '<td valign="top">Quite beautiful! Love the heavy contrast you''ve chosen.</td>', 'Quite beautiful! Love the heavy contrast you''ve chosen.', '2014-08-22 20:30:22.000000', NULL, 1),
(7253887, 1127549, 94815, '<td valign="top">Perfect panoramic subject. Glorious light.</td>', 'Perfect panoramic subject. Glorious light.', '2014-08-22 21:18:24.000000', NULL, 1),
(7253888, 1127496, 94815, '<td valign="top">Lovely framing and detail - and of course a very apt subject.</td>', 'Lovely framing and detail - and of course a very apt subject.', '2014-08-22 21:19:07.000000', NULL, 1),
(7253890, 1127346, 94815, '<td valign="top">Lovely panoramic - more than some, makes my eye meander back and forth. Good subject and perfect crop.</td>', 'Lovely panoramic - more than some, makes my eye meander back and forth. Good subject and perfect crop.', '2014-08-22 21:20:19.000000', NULL, 1),
(7253892, 1127550, 30861, '<td valign="top">Commenting only, voting already done :-)<br/> <br/>I like the image, but I am bothered by the fact that fully half of it is empty space, contributing little to interest me. Now, if you had a BEE hovering over there :-) Also, on my monitor it''s a little washed out on the twig, in general I think it would be stronger if it were about one zone darker/richer.</td>', 'Commenting only, voting already done :-) I like the image, but I am bothered by the fact that fully half of it is empty space, contributing little to interest me. Now, if you had a BEE hovering over there :-) Also, on my monitor it''s a little washed out on the twig, in general I think it would be stronger if it were about one zone darker/richer.', '2014-08-22 21:25:12.000000', NULL, 1),
(7253893, 1127514, 94815, '<td valign="top">Good subject and repetition.</td>', 'Good subject and repetition.', '2014-08-22 21:25:25.000000', NULL, 1),
(7253895, 1127562, 30861, '<td valign="top">Almost certainly the winner. Perfect use of the narrow space.</td>', 'Almost certainly the winner. Perfect use of the narrow space.', '2014-08-22 21:28:17.000000', NULL, 1),
(7253896, 1127118, 94815, '<td valign="top">Very effective panoramic evocative of the location and appropriate subject with repetitions of trees and figures.</td>', 'Very effective panoramic evocative of the location and appropriate subject with repetitions of trees and figures.', '2014-08-22 21:28:23.000000', NULL, 1),
(7253897, 1127588, 30861, '<td valign="top">Right at the top of my list. Wonderful background. Love the ghostly, far-away figure on the right.</td>', 'Right at the top of my list. Wonderful background. Love the ghostly, far-away figure on the right.', '2014-08-22 21:28:59.000000', NULL, 1),
