(7254183, 1127526, 124982, '<td valign="top">Lovely display of color and light!</td>', 'Lovely display of color and light!', '2014-08-23 17:03:35.000000', NULL, 1),
(7254184, 1127098, 124982, '<td valign="top">Quite magnificent! Beautiful sunset, love the purples and blues in the sky!</td>', 'Quite magnificent! Beautiful sunset, love the purples and blues in the sky!', '2014-08-23 17:04:07.000000', NULL, 1),
(7254185, 1127534, 19944, '<td valign="top">I like the abstractness of this.</td>', 'I like the abstractness of this.', '2014-08-23 17:09:38.000000', NULL, 1),
(7254186, 1127402, 60173, '<td valign="top">I like how the city lights sprawl out into the void.</td>', 'I like how the city lights sprawl out into the void.', '2014-08-23 17:10:44.000000', NULL, 1),
(7254188, 1127562, 60173, '<td valign="top">Excellent use of vertical space! It''s interesting from her feet all the way up into the heavens. I also really like that you had her hold the umbrella up so high; it really helps bring the eye up.</td>', 'Excellent use of vertical space! It''s interesting from her feet all the way up into the heavens. I also really like that you had her hold the umbrella up so high; it really helps bring the eye up.', '2014-08-23 17:13:10.000000', NULL, 1),
(7254189, 1127435, 60173, '<td valign="top">More toes! I demand you get those feet all the way up on that ledge! As it is, the feet get lost in the darkness.</td>', 'More toes! I demand you get those feet all the way up on that ledge! As it is, the feet get lost in the darkness.', '2014-08-23 17:14:57.000000', NULL, 1),
(7254190, 1127364, 60173, '<td valign="top">This has the feel of a lovely tapestry.</td>', 'This has the feel of a lovely tapestry.', '2014-08-23 17:17:22.000000', NULL, 1),
(7254191, 1127199, 60173, '<td valign="top">For this image to work in this challenge, I think there needs to be a lot more vertical pixels. As it is now, it just looks like a tiny image rather than an image that works best in say, 800 x 160, which is what I think the intent of the challenge was.</td>', 'For this image to work in this challenge, I think there needs to be a lot more vertical pixels. As it is now, it just looks like a tiny image rather than an image that works best in say, 800 x 160, which is what I think the intent of the challenge was.', '2014-08-23 17:18:57.000000', NULL, 1),
