INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7254227, 1127401, 109227, '<td valign="top">Nice leading lines and the crop works well.  Would look nice framed.</td>', 'Nice leading lines and the crop works well.  Would look nice framed.', '2014-08-23 18:56:25.000000', NULL, 1),
(7254228, 1127505, 149964, '<td valign="top">Really like the simplicity of the lines and circles of this.</td>', 'Really like the simplicity of the lines and circles of this.', '2014-08-23 18:57:03.000000', NULL, 1),
(7254229, 1127098, 109227, '<td valign="top">Nicely done.  The crop works well with the image.  I like the negative space (voted earlier).</td>', 'Nicely done.  The crop works well with the image.  I like the negative space (voted earlier).', '2014-08-23 18:57:24.000000', NULL, 1),
(7254230, 1127260, 109227, '<td valign="top">Nice image for this crop.   The birds are an added bonus. (Voted earlier)</td>', 'Nice image for this crop.   The birds are an added bonus. (Voted earlier)', '2014-08-23 18:58:08.000000', NULL, 1),
(7254231, 1127499, 109227, '<td valign="top">The black background fits well with the crop.  Nice I age. (Voted earlier)</td>', 'The black background fits well with the crop.  Nice I age. (Voted earlier)', '2014-08-23 18:59:08.000000', NULL, 1),
(7254232, 1127527, 149964, '<td valign="top">Great idea!</td>', 'Great idea!', '2014-08-23 18:59:11.000000', NULL, 1),
(7254233, 1127431, 109227, '<td valign="top">I like the unusual viewpoint.</td>', 'I like the unusual viewpoint.', '2014-08-23 18:59:43.000000', NULL, 1),
(7254234, 1127587, 149964, '<td valign="top">Beautiful colours.</td>', 'Beautiful colours.', '2014-08-23 19:00:05.000000', NULL, 1),
(7254235, 1127402, 109227, '<td valign="top">Nice image for the crop.  The crop enhances rather than fights for attention. ( voted earlier)</td>', 'Nice image for the crop.  The crop enhances rather than fights for attention. ( voted earlier)', '2014-08-23 19:00:23.000000', NULL, 1),
(7254236, 1127279, 109227, '<td valign="top">Love this one. And it fits the crop nicely.  Bumping up.</td>', 'Love this one. And it fits the crop nicely.  Bumping up.', '2014-08-23 19:01:31.000000', NULL, 1),
(7254237, 1127495, 109227, '<td valign="top">Love the composition. I would like to see more of her face.  The crop works well. ( voted earlier)</td>', 'Love the composition. I would like to see more of her face.  The crop works well. ( voted earlier)', '2014-08-23 19:03:20.000000', NULL, 1),
(7254239, 1127584, 109227, '<td valign="top">The scene  fits the crop well.</td>', 'The scene  fits the crop well.', '2014-08-23 19:05:33.000000', NULL, 1),
(7254241, 1127364, 109227, '<td valign="top">Nicely composed for the crop.</td>', 'Nicely composed for the crop.', '2014-08-23 19:05:59.000000', NULL, 1),
(7254242, 1127562, 109227, '<td valign="top">A fun image that would look great framed. ( voted earlier)</td>', 'A fun image that would look great framed. ( voted earlier)', '2014-08-23 19:06:33.000000', NULL, 1),
(7254243, 1127199, 149964, '<td valign="top">Clever capture but I wasn''t sure it really met the challenge.</td>', 'Clever capture but I wasn''t sure it really met the challenge.', '2014-08-23 19:07:24.000000', NULL, 1),
(7254244, 1127507, 109227, '<td valign="top">I think this fits the crop well, although I think it would be a little stronger image if it were not so dark.  Maybe a slight curves adjustment. ( voted earlier)</td>', 'I think this fits the crop well, although I think it would be a little stronger image if it were not so dark.  Maybe a slight curves adjustment. ( voted earlier)', '2014-08-23 19:08:32.000000', NULL, 1),
(7254245, 1127582, 109227, '<td valign="top">Wow, that is an evil looking eye.  Nicely composed.</td>', 'Wow, that is an evil looking eye.  Nicely composed.', '2014-08-23 19:10:36.000000', NULL, 1),
(7254248, 1127582, 60862, '<td valign="top">I love that eye and the editing!  You got a 9 from me - the only thing keeping it from a 10 is the space on the right, which seems kind of wasted. I would''ve preferred to either see the face centered, which would move the eye further right, or just crop it off, leaving it a little less than 800 wide.</td>', 'I love that eye and the editing!  You got a 9 from me - the only thing keeping it from a 10 is the space on the right, which seems kind of wasted. I would''ve preferred to either see the face centered, which would move the eye further right, or just crop it off, leaving it a little less than 800 wide.', '2014-08-23 19:45:30.000000', NULL, 1),
(7254249, 1127439, 60862, '<td valign="top">Really interesting combination of elements in this!</td>', 'Really interesting combination of elements in this!', '2014-08-23 19:45:43.000000', NULL, 1),
(7254250, 1127567, 60862, '<td valign="top">I really like the patterns, colors, and the contrast of the vertical bit. I voted this a 9.  I think without the diagonal stuff to the right of the vertical, I would''ve given this a 10.  Or if the vertical were a little further into the frame, so the diagonals to the right were more visible.</td>', 'I really like the patterns, colors, and the contrast of the vertical bit. I voted this a 9.  I think without the diagonal stuff to the right of the vertical, I would''ve given this a 10.  Or if the vertical were a little further into the frame, so the diagonals to the right were more visible.', '2014-08-23 19:46:46.000000', NULL, 1),
(7254251, 1127445, 60862, '<td valign="top">Nice use of the format to get those long ears into the shot!</td>', 'Nice use of the format to get those long ears into the shot!', '2014-08-23 19:47:00.000000', NULL, 1),
(7254252, 1127402, 60862, '<td valign="top">I love the shapes and tones on the right.  Just a bit too much black on the left for me.  Still, an 8!</td>', 'I love the shapes and tones on the right.  Just a bit too much black on the left for me.  Still, an 8!', '2014-08-23 19:47:27.000000', NULL, 1),
(7254254, 1127401, 60862, '<td valign="top">Nice color contrast and use of the vertical format with the bird''s tail.</td>', 'Nice color contrast and use of the vertical format with the bird''s tail.', '2014-08-23 19:48:03.000000', NULL, 1),
(7254255, 1127098, 60862, '<td valign="top">Beautiful silhouetted of the trees and wow, that sun!</td>', 'Beautiful silhouetted of the trees and wow, that sun!', '2014-08-23 19:48:21.000000', NULL, 1),
(7254258, 1127534, 60862, '<td valign="top">Just fantastic shapes and tones! 10 from me.</td>', 'Just fantastic shapes and tones! 10 from me.', '2014-08-23 19:49:53.000000', NULL, 1),
(7254259, 1127549, 60862, '<td valign="top">Beautiful, soft glow, and a really nice use of the format.  10 from me!</td>', 'Beautiful, soft glow, and a really nice use of the format.  10 from me!', '2014-08-23 19:50:07.000000', NULL, 1),
(7254261, 1127562, 60862, '<td valign="top">This image is, to me, EXACTLY what this odd aspect ratio can aspire to produce.  10!</td>', 'This image is, to me, EXACTLY what this odd aspect ratio can aspire to produce.  10!', '2014-08-23 19:50:42.000000', NULL, 1),
(7254262, 1127118, 60862, '<td valign="top">Lovely story-telling shot with lots of details that fit the format perfectly.  10!</td>', 'Lovely story-telling shot with lots of details that fit the format perfectly.  10!', '2014-08-23 19:51:03.000000', NULL, 1),
(7254263, 1127260, 60862, '<td valign="top">I kept waffling on this one.  One part of me wants more detail, but the bigger part of me just loves the color gradient in the sky, the simplicity of the elements, and the way the birds work with the two bits of land on the sides to frame the gorgeous colors.  10!</td>', 'I kept waffling on this one.  One part of me wants more detail, but the bigger part of me just loves the color gradient in the sky, the simplicity of the elements, and the way the birds work with the two bits of land on the sides to frame the gorgeous colors.  10!', '2014-08-23 19:51:48.000000', NULL, 1),
(7254265, 1127283, 60862, '<td valign="top">Beautiful! And a great use of the crazy crop in this challenge. 9!</td>', 'Beautiful! And a great use of the crazy crop in this challenge. 9!', '2014-08-23 19:52:06.000000', NULL, 1),
(7254266, 1127588, 60862, '<td valign="top">Love the energy, contrast between the runners and the foggy landscape, and the way you cropped this. 9!</td>', 'Love the energy, contrast between the runners and the foggy landscape, and the way you cropped this. 9!', '2014-08-23 19:52:29.000000', NULL, 1),
(7254267, 1127586, 60862, '<td valign="top">Terrific use of the odd format in this challenge to highlight those loooong wings. And wonderful, sharp detail. 9!</td>', 'Terrific use of the odd format in this challenge to highlight those loooong wings. And wonderful, sharp detail. 9!', '2014-08-23 19:53:00.000000', NULL, 1),
(7254268, 1127483, 60862, '<td valign="top">Just fantastic! 10.</td>', 'Just fantastic! 10.', '2014-08-23 19:53:58.000000', NULL, 1),
(7254269, 1127213, 60862, '<td valign="top">A bold choice in a challenge filled with shots of natural beauty where everything is sharp.  I really like the way you used the format to divide the image into halves. 9!</td>', 'A bold choice in a challenge filled with shots of natural beauty where everything is sharp.  I really like the way you used the format to divide the image into halves. 9!', '2014-08-23 19:54:58.000000', NULL, 1),
(7254271, 1127431, 60862, '<td valign="top">A great use of the format! Lots of cool details to explore with my eyes. 9!</td>', 'A great use of the format! Lots of cool details to explore with my eyes. 9!', '2014-08-23 19:55:40.000000', NULL, 1),
(7254272, 1127532, 60862, '<td valign="top">Perfect use of this aspect ratio, and a really nice macro with lots of sharp details to check out. 9!</td>', 'Perfect use of this aspect ratio, and a really nice macro with lots of sharp details to check out. 9!', '2014-08-23 19:56:08.000000', NULL, 1),
(7254281, 1127562, 65234, '<td valign="top">Phenomenal!  The light, the detail in the clouds, the wind in her hair, the progression from grey to gold ... everything comes together beautifully, and the aspect ratio works!</td>', 'Phenomenal!  The light, the detail in the clouds, the wind in her hair, the progression from grey to gold ... everything comes together beautifully, and the aspect ratio works!', '2014-08-23 21:38:31.000000', NULL, 1),
(7254282, 1127542, 65234, '<td valign="top">Lovely light and detail.</td>', 'Lovely light and detail.', '2014-08-23 21:38:53.000000', NULL, 1),
(7254283, 1127559, 65234, '<td valign="top">He''s ... well, "cute" probably isn''t the right word.  How about "interesting?"    Traversing his little landscape with what looks like a smile!</td>', 'He''s ... well, "cute" probably isn''t the right word.  How about "interesting?"    Traversing his little landscape with what looks like a smile!', '2014-08-23 21:41:51.000000', NULL, 1),
(7254285, 1127532, 65234, '<td valign="top">Nice subject for this challenge and just the right pose captured.  I like the DOF here.  Makes me feel like the butterfly is ready to challenge me!</td>', 'Nice subject for this challenge and just the right pose captured.  I like the DOF here.  Makes me feel like the butterfly is ready to challenge me!', '2014-08-23 21:43:35.000000', NULL, 1),
(7254286, 1127231, 65234, '<td valign="top">Uh, no thanks.  But it''s still a cool spider, and nicely posed for this challenge.</td>', 'Uh, no thanks.  But it''s still a cool spider, and nicely posed for this challenge.', '2014-08-23 21:44:26.000000', NULL, 1),
(7254287, 1127549, 65234, '<td valign="top">LOVE the golden light.</td>', 'LOVE the golden light.', '2014-08-23 21:44:46.000000', NULL, 1),
(7254289, 1127431, 65234, '<td valign="top">Ha!  I was horrible at using manual typewriters.  Too hard to hit those keys.  Not a technology I miss ;-)</td>', 'Ha!  I was horrible at using manual typewriters.  Too hard to hit those keys.  Not a technology I miss ;-)', '2014-08-23 21:46:21.000000', NULL, 1),
