(7254761, 1127439, 173844, '<td valign="top">Beautifully choreographed, intricate composition and charmingly human.  There''s so much to this slice of life, and it''s perfectly not busy.  A consummate image.</td>', 'Beautifully choreographed, intricate composition and charmingly human.  There''s so much to this slice of life, and it''s perfectly not busy.  A consummate image.', '2014-08-25 00:01:25.000000', NULL, 1),
(7254762, 1127364, 173844, '<td valign="top">Quite pretty and delicate, with a gentle staff of slender branches and melodic counterpoint of leaves and flowers.  And the modest crescendo of a hummingbird.  Very well done.</td>', 'Quite pretty and delicate, with a gentle staff of slender branches and melodic counterpoint of leaves and flowers.  And the modest crescendo of a hummingbird.  Very well done.', '2014-08-25 00:07:26.000000', NULL, 1),
